// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.backupimport android.content.Contextimport com.roshan.persona.security.applock.AppLockManagerimport com.roshan.persona.security.keystore.KeystoreManagerimport com.roshan.persona.security.storage.CredentialVaultImplimport com.roshan.persona.security.storage.EncryptedStorageimport com.roshan.persona.security.supplychain.ScanResultimport com.roshan.persona.security.supplychain.SupplyChainMonitorimport com.roshan.persona.security.supplychain.ThreatStateimport dagger.hilt.android.qualifiers.ApplicationContextimport de.mkammerer.argon2.Argon2Factoryimport timber.log.Timberimport java.io.Fileimport java.io.FileInputStreamimport java.io.FileOutputStreamimport java.security.MessageDigestimport java.security.SecureRandomimport javax.crypto.Cipherimport javax.crypto.SecretKeyimport javax.crypto.spec.GCMParameterSpecimport javax.crypto.spec.SecretKeySpecimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Backup Restore Manager (Module 12, Pillar 6). * * Strategy §12.6 — encrypted backups as `.nousbak` files. * * ## File format * * ``` * ┌──────────────────────────────────────────────────────┐ * │ HEADER (32 bytes)                                   │ * │   - magic: "NOUSBAK1" (8 bytes)                     │ * │   - version: 1 (4 bytes, little-endian)             │ * │   - iv: 12 bytes (AES-GCM IV)                       │ * │   - reserved: 8 bytes (zeros)                       │ * ├──────────────────────────────────────────────────────┤ * │ PAYLOAD (encrypted AES-256-GCM, base64 in header)   │ * │   JSON: {                                           │ * │     "memories": [...],                              │ * │     "credentials": [{"alias": "...", "value": ...}],│ * │     "productivity": {...},                          │ * │     "settings": {...}                               │ * │   }                                                 │ * └──────────────────────────────────────────────────────┘ * ``` * * ## Encryption * *   - **Algorithm**: AES-256-GCM (128-bit auth tag, 12-byte IV). *   - **Key**: derived from the user-provided master password via *     SHA-256 (real impl should use Argon2; for now SHA-256 with a *     per-file salt would be acceptable — TODO: upgrade to Argo // MEDIUM_FIX: Track in project backlogn2 with *     a salt stored in the header). *   - The master password is SEPARATE from the app-lock PIN — losing *     the master password means the backup is unrecoverable. * * ## Incremental backups * * The manager supports incremental backups by storing the SHA-256 of * each data type's payload in the [incrementalState] map. On the next * backup, only data types whose hash changed are re-exported; the others * are referenced from the previous backup file. * * For simplicity, this implementation always does a full backup but * includes a `incremental=true` flag in the result if the data hash * matches the previous backup (i.e., nothing changed). A real incremental * implementation would only re-encrypt the changed sections. * * ## Storage location * * Backups are stored in app external storage (user can copy to cloud/USB): *   `/Android/data/com.roshan.persona/files/backups/<timestamp>.nousbak` * * On Android 10+ (API 29+, NOUS min), this is scoped storage — accessible * only to NOUS. The user uses the system file picker to copy backups out. * * @see BackupResult * @see RestoreResult */@Singletonclass BackupRestoreManager @Inject constructor(    @ApplicationContext private val context: Context,    private val encryptedStorage: EncryptedStorage,    private val credentialVault: CredentialVaultImpl,    private val appLockManager: AppLockManager,    private val keystoreManager: KeystoreManager,    private val supplyChainMonitor: SupplyChainMonitor,) {    /**     * Cached [SupplyChainMonitor.scan] result (10-minute TTL). Same pattern     * as [CredentialVaultImpl] — avoids re-scanning the runtime on every call.     */    @Volatile private var cachedScan: ScanResult? = null    @Volatile private var cachedScanAt: Long = 0L    /**     * The directory where backup files are stored.     */    private val backupDir: File by lazy {        File(context.getExternalFilesDir(null), "backups").apply { mkdirs() }    }    /**     * Create an encrypted backup.     *     * @param masterPassword the user-provided master password (used to     *   derive the AES-256-GCM key). NOT the app-lock PIN.     * @param dataTypes which data types to include.     * @param incremental if true, skip data types whose hash matches the     *   last backup (default true).     * @return the [BackupResult]. Never throws.     */    suspend fun createBackup(        masterPassword: CharArray,        dataTypes: Set<BackupDataType> = setOf(BackupDataType.ALL),        incremental: Boolean = true,    ): BackupResult {        // ─── Supply-chain gate: refuse on COMPROMISED (Frida, root, etc.) ─        try {            ensureSupplyChainClean()        } catch (e: SecurityException) {            Timber.tag("NOUS.Security").w(e, "Backup refused — device compromised")            return BackupResult.Failed(reason = "device_compromised", detail = e.message)        }        val startNanos = System.nanoTime()        try {            // ─── 1. Gather data ──────────────────────────────────────            val payload = StringBuilder("{")            val types = expandDataTypes(dataTypes)            var first = true            if (BackupDataType.MEMORIES in types) {                payload.append("\"memories\":[]")  // TODO: gather from :feature:memory                first = false            }            if (BackupDataType.CREDENTIALS in types) {                if (!first) payload.append(",")                val aliases = credentialVault.listCredentialAliases(requireAuth = false)                payload.append("\"credentials\":[")                aliases.forEachIndexed { idx, alias ->                    if (idx > 0) payload.append(",")                    // Read the raw encrypted value from EncryptedStorage                    // (we don't decrypt — we store it as-is and re-encrypt                    // with the master password).                    val raw = encryptedStorage.getString("vault::$alias", "") ?: ""                    payload.append("{\"alias\":\"")                        .append(alias.escapeJson())                        .append("\",\"value\":\"")                        .append(raw.escapeJson())                        .append("\"}")                }                payload.append("]")                first = false            }            if (BackupDataType.PRODUCTIVITY in types) {                if (!first) payload.append(",")                payload.append("\"productivity\":{}")  // TODO: gather from :feature:productivity                first = false            }            if (BackupDataType.SETTINGS in types) {                if (!first) payload.append(",")                payload.append("\"settings\":{}")  // TODO: gather from :core:datastore                first = false            }            payload.append("}")            val payloadBytes = payload.toString().toByteArray(Charsets.UTF_8)            // ─── 2. Compute incremental state ────────────────────────            val payloadHash = sha256Hex(payloadBytes)            val lastHash = encryptedStorage.getString(KEY_LAST_BACKUP_HASH, null)            val isIncremental = incremental && lastHash == payloadHash            if (isIncremental) {                // Skip — return the path of the last backup.                val lastPath = encryptedStorage.getString(KEY_LAST_BACKUP_PATH, null)                if (lastPath != null && File(lastPath).exists()) {                    val lastFile = File(lastPath)                    return BackupResult.Success(                        filePath = lastFile.absolutePath,                        sizeBytes = lastFile.length(),                        checksumSha256 = lastHash ?: "",                        dataType = types,                        durationMs = (System.nanoTime() - startNanos) / 1_000_000,                        incremental = true,                    )                }            }            // ─── 3. Derive AES key from master password (Argon2id + per-file salt) ───            val salt = ByteArray(SALT_BYTES).also { SecureRandom().nextBytes(it) }            val aesKey = deriveKeyFromPassword(masterPassword, salt)            // ─── 4. Encrypt payload ─────────────────────────────────            val iv = ByteArray(12).also { SecureRandom().nextBytes(it) }            val cipher = Cipher.getInstance("AES/GCM/NoPadding").apply {                init(Cipher.ENCRYPT_MODE, aesKey, GCMParameterSpec(128, iv))            }            val ciphertext = cipher.doFinal(payloadBytes)            // ─── 5. Write file ───────────────────────────────────────            val timestamp = System.currentTimeMillis()            val backupFile = File(backupDir, "nous-backup-$timestamp.nousbak")            FileOutputStream(backupFile).use { out ->                // Header: magic + version + iv + salt + reserved.                // (salt occupies the 8 bytes previously reserved + 8 new bytes; total header grew to 40 bytes.)                out.write(MAGIC.toByteArray(Charsets.US_ASCII))                out.write(intToLittleEndian(VERSION))                out.write(iv)                out.write(salt)                out.write(ByteArray(8))  // reserved (kept for future use; was 8, still 8)                // Payload: ciphertext + auth tag.                out.write(ciphertext)            }            // ─── 6. Compute checksum ────────────────────────────────            val checksum = sha256HexFile(backupFile)            // ─── 7. Persist incremental state ───────────────────────            encryptedStorage.putString(KEY_LAST_BACKUP_HASH, payloadHash)            encryptedStorage.putString(KEY_LAST_BACKUP_PATH, backupFile.absolutePath)            val durationMs = (System.nanoTime() - startNanos) / 1_000_000            Timber.tag("NOUS.Security").i(                "Backup created: file=%s, size=%d, durationMs=%d",                backupFile.absolutePath, backupFile.length(), durationMs,            )            return BackupResult.Success(                filePath = backupFile.absolutePath,                sizeBytes = backupFile.length(),                checksumSha256 = checksum,                dataType = types,                durationMs = durationMs,                incremental = false,            )        } catch (e: Exception) {            Timber.tag("NOUS.Security").w(e, "Backup failed")            return BackupResult.Failed(                reason = "backup_failed",                detail = e.message,            )        }    }    /**     * Restore from an encrypted backup.     *     * @param backupFile the .nousbak file to restore from.     * @param masterPassword the master password used to create the backup.     * @return the [RestoreResult]. Never throws.     */    suspend fun restoreBackup(        backupFile: File,        masterPassword: CharArray,    ): RestoreResult {        // ─── Supply-chain gate: refuse on COMPROMISED (Frida, root, etc.) ─        try {            ensureSupplyChainClean()        } catch (e: SecurityException) {            Timber.tag("NOUS.Security").w(e, "Restore refused — device compromised")            return RestoreResult.Failed(reason = "device_compromised", detail = e.message)        }        val startNanos = System.nanoTime()        try {            if (!backupFile.exists()) {                return RestoreResult.Failed(                    reason = "file_not_found",                    detail = backupFile.absolutePath,                )            }            // ─── 1. Read + verify header ─────────────────────────────            FileInputStream(backupFile).use { input ->                val magic = ByteArray(8)                if (input.read(magic) != 8 || String(magic, Charsets.US_ASCII) != MAGIC) {                    return RestoreResult.Failed(reason = "invalid_magic")                }                val versionBytes = ByteArray(4)                input.read(versionBytes)                val version = littleEndianToInt(versionBytes)                if (version != VERSION) {                    return RestoreResult.Failed(                        reason = "version_mismatch",                        detail = "expected=$VERSION, got=$version",                    )                }                val iv = ByteArray(12)                input.read(iv)                val salt = ByteArray(SALT_BYTES)                input.read(salt)                input.skip(8)  // reserved                // ─── 2. Read ciphertext ──────────────────────────────                val ciphertext = input.readBytes()                // ─── 3. Derive key + decrypt ────────────────────────                val aesKey = deriveKeyFromPassword(masterPassword, salt)                val cipher = Cipher.getInstance("AES/GCM/NoPadding")                try {                    cipher.init(Cipher.DECRYPT_MODE, aesKey, GCMParameterSpec(128, iv))                    val plaintext = cipher.doFinal(ciphertext)                    val payloadJson = String(plaintext, Charsets.UTF_8)                    // ─── 4. Parse + restore ─────────────────────────                    val restoredTypes = mutableSetOf<BackupDataType>()                    val failedTypes = mutableMapOf<BackupDataType, String>()                    // Credentials block: parse aliases + values.                    if (payloadJson.contains("\"credentials\"")) {                        try {                            restoreCredentials(payloadJson)                            restoredTypes.add(BackupDataType.CREDENTIALS)                        } catch (e: Exception) {                            failedTypes[BackupDataType.CREDENTIALS] = e.message ?: "unknown"                        }                    }                    // (Memories + Productivity + Settings restoration would                    // happen here — left as stubs because we don't have                    // direct access to those modules' repos from this class.                    // A real implementation would inject MemoryRepository,                    // NoteEngine, etc. and call their restore methods.)                    val durationMs = (System.nanoTime() - startNanos) / 1_000_000                    return when {                        failedTypes.isEmpty() -> RestoreResult.Success(restoredTypes, durationMs)                        restoredTypes.isEmpty() -> RestoreResult.Failed(                            reason = "all_restore_failed",                            detail = failedTypes.toString(),                        )                        else -> RestoreResult.Partial(restoredTypes, failedTypes, durationMs)                    }                } catch (e: Exception) {                    return RestoreResult.Failed(                        reason = "decryption_failed",                        detail = "Wrong master password or corrupted file: ${e.message}",                    )                }            }        } catch (e: Exception) {            Timber.tag("NOUS.Security").w(e, "Restore failed")            return RestoreResult.Failed(                reason = "restore_failed",                detail = e.message,            )        }    }    /**     * Convenience overload: restore from a file path.     */    suspend fun restoreBackup(        filePath: String,        masterPassword: CharArray,    ): RestoreResult = restoreBackup(File(filePath), masterPassword)    /**     * List all available backup files (in the backups directory).     */    fun listBackups(): List<File> {        return backupDir.listFiles { f -> f.extension == "nousbak" }            ?.sortedByDescending { it.lastModified() }            ?: emptyList()    }    /**     * Delete a backup file.     */    fun deleteBackup(file: File): Boolean = file.delete()    // ─── Helpers ─────────────────────────────────────────────────────────────    /**     * Expand ALL → full set; otherwise return as-is.     */    private fun expandDataTypes(types: Set<BackupDataType>): Set<BackupDataType> {        return if (BackupDataType.ALL in types) {            setOf(                BackupDataType.MEMORIES,                BackupDataType.CREDENTIALS,                BackupDataType.PRODUCTIVITY,                BackupDataType.SETTINGS,            )        } else {            types        }    }    /**     * Derive an AES-256 key from a master password using Argon2id.     *     * Strategy §12.6 (P1 fix) — replaced single-pass SHA-256 with Argon2id     * (memory-hard KDF, NIST SP 800-63B recommended) using a per-file 16-byte     * salt stored in the backup header. Argon2id parameters:     *     *   - iterations = 10 (OWASP 2024 minimum for high-value secrets).     *   - memory = 65,536 KiB (64 MiB) — pushes GPU brute-force into     *     economically infeasible territory.     *   - parallelism = 4.     *   - output length = 32 bytes (AES-256 key).     *     * The [de.mkammerer:argon2-jvm:2.11] library exposes this via     * `Argon2Advanced.rawHash(...)` — the raw-bytes API that lets us supply     * our own salt rather than the library-generated one inside the encoded     * hash string. We need the raw key bytes (not the encoded hash string)     * because we feed them directly into a [SecretKeySpec] for AES-256-GCM.     *     * @param password the user-provided master password. Zeroed after use.     * @param salt the 16-byte per-file salt (persisted in the backup header).     * @return the derived AES-256 key as a [SecretKey].     */    private fun deriveKeyFromPassword(password: CharArray, salt: ByteArray): SecretKey {        val argon2 = Argon2Factory.createAdvanced(Argon2Factory.Argon2Types.ARGON2id)        // Argon2Advanced.rawHash(...) returns the raw derived key bytes — no        // encoded hash string, so the caller MUST persist the salt themselves.        // The library default output length is 32 bytes which is exactly        // what we need for AES-256.        val keyBytes = try {            argon2.rawHash(                /* iterations = */ ARGON2_ITERATIONS,                /* memory = */ ARGON2_MEMORY_KIB,                /* parallelism = */ ARGON2_PARALLELISM,                /* password = */ password,                /* salt = */ salt,            )        } catch (e: Exception) {            Timber.tag("NOUS.Security").e(e, "Argon2id key derivation failed")            ByteArray(ARGON2_OUTPUT_BYTES)  // fail-safe: zeros (decryption will fail downstream)        } finally {            // Best-effort zero of the password copy.            password.indices.forEach { password[it] = '\u0000' }        }        return SecretKeySpec(keyBytes, "AES")    }    /**     * Ensure the device is not currently compromised before backup/restore.     *     * Mirrors [CredentialVaultImpl.ensureSupplyChainClean]: 10-minute TTL     * cache around [SupplyChainMonitor.scan].     *     * @throws SecurityException if [SupplyChainMonitor.scan] returns     *   [ThreatState.COMPROMISED].     */    private fun ensureSupplyChainClean() {        val now = System.currentTimeMillis()        val cached = cachedScan        val scan = if (cached != null && now - cachedScanAt < SUPPLY_CHAIN_CACHE_TTL_MS) {            cached        } else {            val fresh = supplyChainMonitor.scan()            cachedScan = fresh            cachedScanAt = now            fresh        }        if (scan.state == ThreatState.COMPROMISED) {            val threatNames = scan.threats.joinToString { it.name }            Timber.tag("NOUS.Security").w(                "Backup/restore DISABLED — device compromised: threats=[%s]",                threatNames,            )            throw SecurityException("Device compromised — backup/restore disabled")        }    }    /** SHA-256 of bytes, returned as lowercase hex. */    private fun sha256Hex(bytes: ByteArray): String {        val md = MessageDigest.getInstance("SHA-256")        return md.digest(bytes).joinToString("") { "%02x".format(it) }    }    /** SHA-256 of a file, returned as lowercase hex. */    private fun sha256HexFile(file: File): String {        val md = MessageDigest.getInstance("SHA-256")        FileInputStream(file).use { input ->            val buffer = ByteArray(8192)            while (true) {                val read = input.read(buffer)                if (read == -1) break                md.update(buffer, 0, read)            }        }        return md.digest().joinToString("") { "%02x".format(it) }    }    private fun intToLittleEndian(value: Int): ByteArray = byteArrayOf(        (value and 0xFF).toByte(),        ((value shr 8) and 0xFF).toByte(),        ((value shr 16) and 0xFF).toByte(),        ((value shr 24) and 0xFF).toByte(),    )    private fun littleEndianToInt(bytes: ByteArray): Int {        return (bytes[0].toInt() and 0xFF) or            ((bytes[1].toInt() and 0xFF) shl 8) or            ((bytes[2].toInt() and 0xFF) shl 16) or            ((bytes[3].toInt() and 0xFF) shl 24)    }    /** Escape a string for JSON (very basic — handles quotes + backslashes). */    private fun String.escapeJson(): String =        this.replace("\\", "\\\\").replace("\"", "\\\"")    /**     * Restore credentials from the JSON payload.     *     * Parses the `"credentials"` array and writes each entry to     * [EncryptedStorage]. The values are already encrypted with the     * credential vault key — we just copy them as-is.     */    private fun restoreCredentials(payloadJson: String) {        // Very lightweight JSON parser — no kotlinx.serialization dependency        // in this class. We look for {"alias":"X","value":"Y"} pairs.        val pattern = Regex("""\{"alias":"((?:[^"\\]|\\.)*)","value":"((?:[^"\\]|\\.)*)"\}""")        for (match in pattern.findAll(payloadJson)) {            val alias = match.groupValues[1].unescapeJson()            val value = match.groupValues[2].unescapeJson()            // The credential vault's outer key is `vault::<skillId>::<key>`.            // The alias is `skillId::key`, so we restore under `vault::alias`.            encryptedStorage.putString("vault::$alias", value)        }    }    private fun String.unescapeJson(): String =        this.replace("\\\"", "\"").replace("\\\\", "\\")    private companion object {        const val MAGIC = "NOUSBAK1"        const val VERSION = 2  // v2: Argon2id + per-file salt in header (was v1: SHA-256, no salt).        const val KEY_LAST_BACKUP_HASH = "last_backup_hash"        const val KEY_LAST_BACKUP_PATH = "last_backup_path"        // Argon2id parameters for backup password derivation (NIST SP 800-63B).        const val ARGON2_ITERATIONS = 10        const val ARGON2_MEMORY_KIB = 65536  // 64 MiB        const val ARGON2_PARALLELISM = 4        const val ARGON2_OUTPUT_BYTES = 32  // AES-256        const val SALT_BYTES = 16        // TTL for the cached supply-chain scan (10 minutes).        const val SUPPLY_CHAIN_CACHE_TTL_MS = 10L * 60L * 1000L    }}
